{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "Apple (light appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never delete finish fields or alter the merged finish key set across appearances or themes."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "Apple Human Interface Guidelines / UIKit system palette (`systemBlue`, `systemGroupedBackground`, `label`) with Retina 0.5px hairlines, capsule buttons, continuous corners, and Liquid Glass on floating and raised surfaces.",
        "elevation": "Apple Liquid Glass and Retina hairline depth: `glass`, `menu`, and `raised` finishes request `material.apple` (`glass: \"regular\"`) with iOS backdrop fallback (`ios.backdrop`) and 0.5px borders; other surfaces stay flat with subtle shadows.",
        "dos": [
          "Use `999px` capsule corners on button-like controls (`shape.corners.button: \"full\"`) alongside `8px` controls/fields, `12px` containers, and `26px` modals with `shape.curve: \"continuous\"`.",
          "Respect pointer (macOS: 13px body, 32px density row) vs touch (iOS: 17px body, 44px hit target) metrics.",
          "Keep `material.apple` on `glass`, `menu`, and `raised` finishes and spread `platformMaterial()` on native views."
        ],
        "donts": [
          "Do not replace Retina `0.5px` `stroke.hairline` with thick borders or `circular` corners.",
          "Do not set `macos.backdrop` when Liquid Glass `glassEffect` is active on macOS 26+."
        ]
      },
      "contrast": {
        "waivers": [
          {
            "fg": "muted-foreground",
            "bg": "background",
            "source": "Apple secondaryLabel (#3C3C43 at 60%)"
          },
          {
            "fg": "muted-foreground",
            "bg": "muted",
            "source": "Apple secondaryLabel (#3C3C43 at 60%)"
          },
          {
            "fg": "muted-foreground",
            "bg": "card",
            "source": "Apple secondaryLabel (#3C3C43 at 60%)"
          },
          {
            "fg": "muted-foreground",
            "bg": "raised",
            "source": "Apple secondaryLabel (#3C3C43 at 60%)"
          },
          {
            "fg": "primary-foreground",
            "bg": "primary",
            "source": "white on Apple systemBlue"
          },
          {
            "fg": "sidebar-primary-foreground",
            "bg": "sidebar-primary",
            "source": "white on Apple systemBlue"
          },
          {
            "fg": "primary-foreground",
            "bg": "finish.accent",
            "source": "white on Apple systemBlue"
          },
          {
            "fg": "primary-foreground",
            "bg": "finish.fill",
            "source": "white on Apple systemBlue"
          },
          {
            "fg": "brand",
            "bg": "background",
            "source": "Apple systemBlue links"
          }
        ]
      }
    }
  },
  "cubicBezier": {
    "$type": "cubicBezier",
    "$description": "Named timing curves shared across themes.",
    "out-cubic": {
      "$value": [
        0.333333,
        1,
        0.666667,
        1
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.out(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "out-cubic"
        }
      }
    },
    "in-cubic": {
      "$value": [
        0.333333,
        0,
        0.666667,
        0
      ],
      "$description": "Exact cubic-bezier equivalent of NSH Easing.in(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-cubic"
        }
      }
    },
    "in-out-cubic": {
      "$value": [
        0.65,
        0,
        0.35,
        1
      ],
      "$description": "Cubic approximation of NSH Easing.inOut(Easing.cubic).",
      "$extensions": {
        "dev.aning.shadcn-nsh": {
          "nshEasing": "in-out-cubic"
        }
      }
    },
    "standard": {
      "$value": [
        0.2,
        0,
        0,
        1
      ],
      "$description": "Material 3 md.sys.motion.easing.standard."
    },
    "emphasized-decelerate": {
      "$value": [
        0.05,
        0.7,
        0.1,
        1
      ],
      "$description": "Material 3 emphasized-decelerate curve."
    },
    "emphasized-accelerate": {
      "$value": [
        0.3,
        0,
        0.8,
        0.15
      ],
      "$description": "Material 3 emphasized-accelerate curve."
    },
    "decelerate": {
      "$value": [
        0,
        0,
        0,
        1
      ],
      "$description": "WinUI 3 Fast Out, Slow In curve (entering elements)."
    },
    "accelerate": {
      "$value": [
        1,
        0,
        1,
        1
      ],
      "$description": "WinUI 3 Slow Out, Fast In curve (exiting elements)."
    },
    "point-to-point": {
      "$value": [
        0.55,
        0.55,
        0,
        1
      ],
      "$description": "WinUI 3 Point-to-Point motion curve."
    }
  },
  "typography": {
    "$type": "typography",
    "$description": "Semantic typography roles referencing tier-specific font.size and font.line-height.",
    "caption": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.caption}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.caption}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Small captions and segmented counter labels."
    },
    "detail": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.detail}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.detail}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Sidebar section labels, counts, and supporting metadata."
    },
    "body": {
      "$value": {
        "fontFamily": "{font.family.sans}",
        "fontSize": "{font.size.body}",
        "fontWeight": 400,
        "lineHeight": "{font.line-height.body}",
        "letterSpacing": {
          "value": 0,
          "unit": "px"
        }
      },
      "$description": "Standard body copy, list rows, and dialog content."
    },
    "label": {
