{
  "$schema": "https://www.designtokens.org/schemas/2025.10/format.json",
  "$description": "Apple (dark appearance, pointer tier) — standalone W3C DTCG 2025.10 tokens.",
  "$extensions": {
    "dev.aning.shadcn-nsh": {
      "designMd": {
        "sharedDos": [
          "Read all colors, radii, typography, and surface finishes through theme roles (`colors.*`, `shape.*`, `font.*`, `finish.*`) rather than literals in component code.",
          "Read theme getters inside JSX render expressions or reactive effects so runtime theme switching (`selectTheme`) and light/dark appearance changes take effect on the next frame.",
          "Use `rounded(shape.<role>, inset)` for concentric nested radii inside cards, switches, and segmented controls."
        ],
        "sharedDonts": [
          "Never write color literals (`#...`, `rgb()`, `oklch()`) in component, lib, or demo-adapter code.",
          "Never store `colors.*`, `finish.*`, or `shape.*` values in module-level constants; they freeze on theme or appearance switches.",
          "Never delete finish fields or alter the merged finish key set across appearances or themes."
        ],
        "voiceOmitted": "Voice & Content Strategy is intentionally omitted: this theme defines visual tokens, surface finishes, typography metrics, and motion physics only; product copy, tone, capitalization, and terminology belong to the host application.",
        "overview": "Apple Human Interface Guidelines / UIKit system palette (`systemBlue`, `systemGroupedBackground`, `label`) with Retina 0.5px hairlines, capsule buttons, continuous corners, and Liquid Glass on floating and raised surfaces.",
        "elevation": "Apple Liquid Glass and Retina hairline depth: `glass`, `menu`, and `raised` finishes request `material.apple` (`glass: \"regular\"`) with iOS backdrop fallback (`ios.backdrop`) and 0.5px borders; other surfaces stay flat with subtle shadows.",
        "dos": [
          "Use `999px` capsule corners on button-like controls (`shape.corners.button: \"full\"`) alongside `8px` controls/fields, `12px` containers, and `26px` modals with `shape.curve: \"continuous\"`.",
          "Respect pointer (macOS: 13px body, 32px density row) vs touch (iOS: 17px body, 44px hit target) metrics.",
          "Keep `material.apple` on `glass`, `menu`, and `raised` finishes and spread `platformMaterial()` on native views."
        ],
        "donts": [
          "Do not replace Retina `0.5px` `stroke.hairline` with thick borders or `circular` corners.",
          "Do not set `macos.backdrop` when Liquid Glass `glassEffect` is active on macOS 26+."
        ]
      },
      "contrast": {
        "waivers": [
          {
            "fg": "muted-foreground",
            "bg": "background",
            "source": "Apple secondaryLabel (#3C3C43 at 60%)"
          },
          {
